ntUnit!==(int)$personUnit)abort(422,'Người thay thế phải thuộc cùng đơn vị với quân nhân nghỉ.');}});static::creating(function(self $request):void{if($request->personnel_id)LeaveAccess::ensurePersonnel((int)$request->personnel_id,Auth::user());});} public function personnel(){return $this->belongsTo(LeavePersonnel::class,'personnel_id');} public function leaveClass(){return $this->belongsTo(LeaveClass::class,'class_id');} public function commander(){return $this->belongsTo(\App\Models\User::class,'commander_user_id');} public function replacement(){return $this->belongsTo(LeavePersonnel::class,'replacement_personnel_id');} }
